INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 2, 'theory', 'Quiz: Variables');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 0, 'What happens with let x = 5; x = 6;?', '["x becomes 6", "Compile error: the variable is immutable, mut is needed", "A panic at run time", "The value stays 5 with no error"]', 1, 'Variables are immutable by default. Add mut: let mut x = 5; then the assignment is allowed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 1, 'What is the difference between let mut x and shadowing with let x = x + 1?', '["mut changes the value in place and keeps the type; shadowing creates a new variable and can change the type", "There is no difference", "Shadowing only works with numbers", "mut cannot be used inside functions"]', 0, 'Shadowing is a new declaration with let; the old variable is covered. This lets you turn a string into a number under the same name.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 2, 'What must you always specify for a const?', '["Nothing", "The word mut", "The type of the value", "A lowercase name"]', 2, 'const MAX: u32 = 100; — the type is required, the value is computed at compile time, and the name is conventionally written in CAPITAL_LETTERS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 3, 'Can you store a string in a variable x: i32?', '["Yes, like in Python", "Yes, if the variable is mut", "Only inside a block", "No: a variable''s type does not change — mismatched types error"]', 3, 'Rust is statically typed: the type is known at build time and does not change. A new type is obtained through shadowing with let.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 4, 'How long does a variable declared inside a block { … } live?', '["Until the end of the program", "From its declaration to the closing curly brace of the block", "Only on one line", "Until it is shadowed"]', 1, 'Scope is limited by the block; on exit the variable is destroyed.');
